package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.*;import com.makemytrip.makemytrip.repositories.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@Service public class RecommendationService{private final BookingRepository bookings;private final FlightRepository flights;private final HotelRepository hotels;private final RecommendationRepository recommendations;public RecommendationService(BookingRepository b,FlightRepository f,HotelRepository h,RecommendationRepository r){bookings=b;flights=f;hotels=h;recommendations=r;}
 public List<Recommendation> forUser(String user){List<Booking> history=bookings.findByUserId(user);Map<String,Integer> destinationCounts=new HashMap<>();Set<String> booked=new HashSet<>();for(Booking b:history){if(b.getProductId()!=null)booked.add(b.getProductId());if(b.getBookingType()==Booking.Type.FLIGHT)flights.findById(b.getFlightId()).ifPresent(f->{if(f.getTo()!=null)destinationCounts.merge(f.getTo(),1,Integer::sum);});}if(destinationCounts.isEmpty())return List.of();List<Recommendation> out=new ArrayList<>();for(var e:destinationCounts.entrySet()){String destination=e.getKey();int n=e.getValue();flights.findAll().stream().filter(f->destination.equalsIgnoreCase(f.getTo())&&!booked.contains(f.getId())).forEach(f->out.add(upsert(user,Recommendation.Type.FLIGHT,f.getId(),f.getFlightNumber(),"You have booked flights to "+destination+" before, so this flight serves a destination you prefer.",n)));hotels.findAll().stream().filter(h->destination.equalsIgnoreCase(h.getLocation())&&!booked.contains(h.getId())).forEach(h->out.add(upsert(user,Recommendation.Type.HOTEL,h.getId(),h.gethotelName(),"You have travelled to "+destination+" before, so we found a stay in a place you prefer.",n)));}return out.stream().filter(r->r.getFeedback()!=Recommendation.Feedback.NOT_INTERESTED).sorted(Comparator.comparingDouble(Recommendation::getScore).reversed()).limit(10).toList();}
 public Recommendation feedback(String id,String user,Recommendation.Feedback feedback){if(feedback==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"feedback is required");Recommendation r=recommendations.findByIdAndUserId(id,user).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Recommendation not found"));r.setFeedback(feedback);if(feedback==Recommendation.Feedback.HELPFUL)r.setScore(r.getScore()+2);if(feedback==Recommendation.Feedback.NOT_HELPFUL)r.setScore(Math.max(0,r.getScore()-2));return recommendations.save(r);}
 private Recommendation upsert(String user,Recommendation.Type type,String id,String title,String reason,double score){Recommendation r=recommendations.findByUserIdAndTargetIdAndRecommendationType(user,id,type).orElseGet(Recommendation::new);r.setUserId(user);r.setRecommendationType(type);r.setTargetId(id);r.setTitle(title);r.setReason(reason);if(r.getFeedback()==null)r.setScore(score);return recommendations.save(r);}
}
